### Use Case 2: Populate a Dropdown Menu

**Scenario:** You're building a web form and need to populate a dropdown with SE machines.

**Solution:**
```javascript
// HTML: <select id="machineDropdown"></select>

fetch('https://eats.pok.stglabs.ibm.com/eATS/local/eatsservice/sakpackua')
    .then(response => response.json())
    .then(data => {
        if (data.success) {
            const dropdown = document.getElementById('machineDropdown');

// Add default option
            dropdown.innerHTML = '<option value="">Select a machine...</option>';

// Add machines
            Object.entries(data.machines).forEach(([machineName, machineData]) => {
                const option = document.createElement('option');
                option.value = machineName;
                option.text = `${machineName} (${machineData.sakPackUA})`;
                dropdown.appendChild(option);
            });
        }
    });
